import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

const PRESET = Object.freeze({
  // V31.4-A — organic iridescent flow over the existing contour-line geometry.
  // The scan lines remain crisp; colour is generated by a multi-scale warped flow field.
  frequency: 8.35,
  depthWarp: 1.28,
  lineWidth: 0.026,
  noiseStrength: 0.17,
  noiseScale: 0.92,
  glow: 0.52,
  bloom: 0.012,
  mouseAmount: 0.72,
  drift: 0.026,
  fadeLow: 0.16,
  fadeHigh: 0.29
});

const PERFORMANCE = Object.freeze({
  // Keep GPU cost bounded by rendered pixels, not by the physical display size.
  // This is what makes the same composition scale from laptop screens to 4K/5K displays.
  largeSurfaceThreshold: 3500000,
  quality: Object.freeze([
    Object.freeze({ name: 'high',     maxPixels: 2200000, maxDpr: 1.25, fps: 60 }),
    Object.freeze({ name: 'balanced', maxPixels: 1400000, maxDpr: 1.00, fps: 60 }),
    Object.freeze({ name: 'low',      maxPixels: 850000,  maxDpr: 0.80, fps: 30 })
  ]),
  touchMaxPixels: 850000,
  touchMaxDpr: 0.85,
  touchFps: 30,
  slowFrameFactor: 1.42,
  slowFrameFloor: 24,
  slowFramesToDegrade: 24
});


const vertexShader = /* glsl */`
  varying vec3 vLocalPos;
  varying vec3 vViewPos;
  varying vec3 vViewNormal;
  void main() {
    vLocalPos = position;
    vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
    vViewPos = mvPosition.xyz;
    vViewNormal = normalize(normalMatrix * normal);
    gl_Position = projectionMatrix * mvPosition;
  }
`;

const fragmentShader = /* glsl */`
  precision highp float;
  uniform float uTime;
  uniform float uFrequency;
  uniform float uDepthWarp;
  uniform float uLineWidth;
  uniform float uNoiseStrength;
  uniform float uNoiseScale;
  uniform float uGlow;
  uniform float uPhase;
  uniform vec3 uBoundsMin;
  uniform vec3 uBoundsMax;
  uniform float uFadeLow;
  uniform float uFadeHigh;
  varying vec3 vLocalPos;
  varying vec3 vViewPos;
  varying vec3 vViewNormal;

  float hash31(vec3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.yzx + 33.33);
    return fract((p.x + p.y) * p.z);
  }
  float noise3(vec3 x) {
    vec3 i = floor(x);
    vec3 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    float n000 = hash31(i + vec3(0.0, 0.0, 0.0));
    float n100 = hash31(i + vec3(1.0, 0.0, 0.0));
    float n010 = hash31(i + vec3(0.0, 1.0, 0.0));
    float n110 = hash31(i + vec3(1.0, 1.0, 0.0));
    float n001 = hash31(i + vec3(0.0, 0.0, 1.0));
    float n101 = hash31(i + vec3(1.0, 0.0, 1.0));
    float n011 = hash31(i + vec3(0.0, 1.0, 1.0));
    float n111 = hash31(i + vec3(1.0, 1.0, 1.0));
    float nx00 = mix(n000, n100, f.x);
    float nx10 = mix(n010, n110, f.x);
    float nx01 = mix(n001, n101, f.x);
    float nx11 = mix(n011, n111, f.x);
    float nxy0 = mix(nx00, nx10, f.y);
    float nxy1 = mix(nx01, nx11, f.y);
    return mix(nxy0, nxy1, f.z);
  }
  float fbm(vec3 p) {
    float value = 0.0;
    float amplitude = 0.52;
    // Three octaves retain the broad organic flow while cutting a quarter of
    // the procedural noise work executed for every rendered head pixel.
    for (int i = 0; i < 3; i++) {
      value += amplitude * noise3(p);
      p = p * 2.03 + vec3(7.13, 11.71, 5.37);
      amplitude *= 0.50;
    }
    return value;
  }

  vec3 iridescentPalette(float t) {
    // Cyclic reference palette: violet -> lilac -> cream -> peach -> orange -> lilac -> violet.
    // Values are deliberately less HDR than previous versions so hue survives tone mapping.
    vec3 violet = vec3(0.44, 0.28, 1.55);
    vec3 lilac = vec3(0.82, 0.63, 1.70);
    vec3 lilacLight = vec3(1.15, 0.98, 1.78);
    vec3 cream = vec3(1.76, 1.50, 1.18);
    vec3 peach = vec3(1.98, 1.13, 0.70);
    vec3 orange = vec3(2.20, 0.73, 0.16);

    t = fract(t);
    if (t < 0.16) return mix(violet, lilac, smoothstep(0.00, 0.16, t));
    if (t < 0.31) return mix(lilac, lilacLight, smoothstep(0.16, 0.31, t));
    if (t < 0.44) return mix(lilacLight, cream, smoothstep(0.31, 0.44, t));
    if (t < 0.59) return mix(cream, peach, smoothstep(0.44, 0.59, t));
    if (t < 0.74) return mix(peach, orange, smoothstep(0.59, 0.74, t));
    if (t < 0.88) return mix(orange, lilac, smoothstep(0.74, 0.88, t));
    return mix(lilac, violet, smoothstep(0.88, 1.00, t));
  }

  float organicFlow(vec3 npos, float time) {
    // Domain-warped 3D field. The first octave bends the coordinate domain,
    // the second creates broad liquid streams, and the third adds small continuous eddies.
    vec3 p = vec3(
      npos.x * 1.42,
      npos.y * 1.10,
      npos.z * 1.48
    );

    vec3 q = vec3(
      fbm(p * 1.10 + vec3(0.0, 0.0, time * 0.30)),
      fbm(p * 1.10 + vec3(5.2, 1.3, -time * 0.23)),
      fbm(p * 1.10 + vec3(-3.7, 4.1, time * 0.19))
    );

    vec3 r = vec3(
      fbm(p * 1.42 + q * 2.15 + vec3(1.7, 9.2, 2.8)),
      fbm(p * 1.42 + q * 2.15 + vec3(8.3, 2.8, 5.1)),
      fbm(p * 1.42 + q * 2.15 + vec3(3.1, 6.4, 9.7))
    );

    float broad = fbm(p * 1.20 + q * 2.35 + r * 1.55 + vec3(time * 0.09, 0.0, -time * 0.07));
    float mid = fbm(p * 2.15 + r * 1.65 + vec3(-time * 0.05, time * 0.07, 0.0));
    float fine = fbm(p * 3.55 + q * 1.15 + r * 0.65);

    // A gentle directional sweep prevents the result from collapsing into isolated spots.
    float sweep = npos.y * 0.72 + npos.x * 0.22 - npos.z * 0.31;
    return sweep
      + (broad - 0.5) * 1.72
      + (q.x - q.y) * 0.48
      + (r.z - r.x) * 0.34
      + (mid - 0.5) * 0.42
      + (fine - 0.5) * 0.16;
  }
  void main() {
    vec3 boundsSize = max(uBoundsMax - uBoundsMin, vec3(0.0001));
    vec3 npos = clamp((vLocalPos - uBoundsMin) / boundsSize, 0.0, 1.0);

    float scanCoord = vViewPos.x + vViewPos.z * uDepthWarp;
    float organic = noise3(vec3(
      vLocalPos.x * uNoiseScale,
      vLocalPos.y * uNoiseScale * 0.74,
      vLocalPos.z * uNoiseScale + uTime * 0.060
    )) - 0.5;
    float organic2 = noise3(vLocalPos * (uNoiseScale * 1.75) + vec3(3.2, -1.6, uTime * 0.035)) - 0.5;
    scanCoord += (organic * 1.80 + organic2 * 0.42) * uNoiseStrength;

    float p = scanCoord * uFrequency + uPhase;
    float bandId = floor(p);
    float jitter = (hash31(vec3(bandId, bandId * 0.071, 4.13)) - 0.5) * 0.035;
    float d = abs(fract(p + jitter) - 0.5);
    float aa = max(fwidth(p), 0.00035);

    float core = 1.0 - smoothstep(uLineWidth, uLineWidth + aa * 0.90, d);
    float innerGlow = 1.0 - smoothstep(uLineWidth + 0.010, uLineWidth + 0.060 + aa * 1.40, d);
    float outerGlow = 1.0 - smoothstep(uLineWidth + 0.050, uLineWidth + 0.145 + aa * 2.10, d);
    float hotCore = 1.0 - smoothstep(max(uLineWidth * 0.34, 0.004), max(uLineWidth * 0.34, 0.004) + aa * 0.70, d);

    vec3 N = normalize(vViewNormal);
    vec3 V = normalize(-vViewPos);
    float facing = clamp(dot(N, V), 0.0, 1.0);
    float edge = pow(1.0 - facing, 1.70);
    float lowerMask = smoothstep(uFadeLow, uFadeHigh, npos.y);

    // Continuous, animated colour flow. Two nearby warped samples are blended so the palette
    // never reads as isolated warm/cool zones and instead behaves like liquid iridescence.
    float flowTime = uTime * 0.42;
    float flowA = organicFlow(npos, flowTime);
    vec3 offsetPos = clamp(npos + vec3(0.055, -0.036, 0.048), 0.0, 1.0);
    float flowB = organicFlow(offsetPos, flowTime + 1.73);
    float detail = fbm(npos * 4.20 + vec3(flowTime * 0.035, -flowTime * 0.025, 2.7));

    float paletteT1 = fract(flowA * 1.26 + detail * 0.16 + uTime * 0.006);
    float paletteT2 = fract(flowB * 1.18 - detail * 0.11 + 0.18 + uTime * 0.004);
    float blendFlow = smoothstep(0.18, 0.82, fbm(npos * 2.55 + vec3(4.2, 1.7, 8.1)));

    vec3 colorA = iridescentPalette(paletteT1);
    vec3 colorB = iridescentPalette(paletteT2);
    vec3 lineColor = mix(colorA, colorB, blendFlow * 0.34);

    // Small continuous hue drift across each line, not a separate colour zone.
    float microT = fract(paletteT1 + (detail - 0.5) * 0.13 + flowB * 0.055);
    lineColor = mix(lineColor, iridescentPalette(microT), 0.22);
    lineColor *= 0.98 + facing * 0.12;

    vec3 haloColor = mix(lineColor, vec3(1.04, 0.88, 1.55), 0.035 + edge * 0.025);

    // The colour should feel luminous inside the line, not surrounded by a neon fog.
    float lineEnergy = core * 1.22 + innerGlow * 0.042 * uGlow + outerGlow * 0.0015 * uGlow;
    vec3 finalColor = lineColor * lineEnergy;
    finalColor += haloColor * outerGlow * edge * 0.006;

    // Very tight cream highlight only on the thinnest core.
    vec3 hotCream = vec3(2.18, 1.94, 1.58);
    finalColor = mix(finalColor, hotCream * 0.76, hotCore * (0.018 + facing * 0.030));

    // Minimal violet/lilac rim for volume.
    finalColor += mix(vec3(0.08, 0.035, 0.22), vec3(0.18, 0.085, 0.35), paletteT1) * edge * 0.012;
    finalColor *= lowerMask;
    gl_FragColor = vec4(finalColor, 1.0);
  }
`;

function disposeModel(model) {
  const geometries = new Set(), materials = new Set(), textures = new Set();
  model?.traverse(object => {
    if (!object.isMesh) return;
    geometries.add(object.geometry);
    for (const material of [].concat(object.material)) {
      if (!material) continue;
      materials.add(material);
      for (const value of Object.values(material)) if (value?.isTexture) textures.add(value);
    }
  });
  geometries.forEach(geometry => geometry.dispose());
  materials.forEach(material => material.dispose());
  textures.forEach(texture => texture.dispose());
}

// V31.4-A contour-line shader with multi-scale domain-warped organic iridescent colour flow.
export function mountHeadScanEffect({ container, canvas, modelUrl, reducedMotion = false, onError } = {}) {
  if (!container || !canvas) throw new Error('Head scan requires its container and canvas.');
  let renderer, composer, outputPass, resizeObserver, model;
  let disposed = false, loaded = false, paused = true, raf = 0, lastTime = null, elapsed = 0;
  let lastFrameStamp = 0, lastRafStamp = 0, slowFrameStreak = 0;
  let shaderFailed = false;
  const coarsePointer = matchMedia('(pointer: coarse)').matches;
  const estimateSurfacePixels = () => {
    const width = Math.max(container.clientWidth, 1);
    const height = Math.max(container.clientHeight, 1);
    const dpr = Math.min(devicePixelRatio || 1, 1.5);
    return width * height * dpr * dpr;
  };
  let qualityIndex = coarsePointer ? 1 : (estimateSurfacePixels() > PERFORMANCE.largeSurfaceThreshold ? 1 : 0);
  const quality = () => PERFORMANCE.quality[qualityIndex];
  const targetFps = () => coarsePointer ? PERFORMANCE.touchFps : quality().fps;
  const targetFrameMs = () => 1000 / targetFps();

  function syncPerformanceClass() {
    const estimated = estimateSurfacePixels();
    document.body.classList.toggle('perf-head-large', estimated > PERFORMANCE.largeSurfaceThreshold);
    document.body.classList.toggle('perf-constrained', qualityIndex >= 2);
    document.body.classList.toggle(
      'perf-large-surface',
      document.body.classList.contains('perf-head-large') ||
      document.body.classList.contains('perf-crt-large') ||
      qualityIndex >= 2
    );
    document.body.dataset.renderQuality = coarsePointer ? 'touch' : quality().name;
  }

  function degradeQuality() {
    if (coarsePointer || qualityIndex >= PERFORMANCE.quality.length - 1) return false;
    qualityIndex += 1;
    slowFrameStreak = 0;
    syncPerformanceClass();
    resize();
    return true;
  }

  function sampleFramePacing(now) {
    if (!lastRafStamp) {
      lastRafStamp = now;
      return;
    }
    const delta = now - lastRafStamp;
    lastRafStamp = now;
    const slowThreshold = Math.max(PERFORMANCE.slowFrameFloor, targetFrameMs() * PERFORMANCE.slowFrameFactor);
    if (delta > slowThreshold) slowFrameStreak += 1;
    else slowFrameStreak = Math.max(0, slowFrameStreak - 2);
    if (slowFrameStreak >= PERFORMANCE.slowFramesToDegrade) degradeQuality();
  }
  const materials = [];
  const pointer = new THREE.Vector2(), targetPointer = new THREE.Vector2();
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x000000);
  const camera = new THREE.PerspectiveCamera(42, 1, 0.05, 50);
  camera.position.set(0, 0, 5.25);
  const root = new THREE.Group();
  root.position.y = 0.02;
  root.rotation.x = -0.015;
  scene.add(root);
  const fitCenter = new THREE.Vector2();
  let fitX = 1, fitY = 1;

  function destroy() {
    if (disposed) return;
    disposed = true;
    cancelAnimationFrame(raf);
    resizeObserver?.disconnect();
    removeEventListener('resize', resize);
    canvas.removeEventListener('webglcontextlost', onContextLost);
    disposeModel(model);
    outputPass?.dispose();
    composer?.dispose();
    renderer?.dispose();
    root.clear();
  }
  function fail(error) {
    if (disposed) return;
    destroy();
    onError?.(error);
  }
  function onContextLost() { fail(new Error('WebGL context lost.')); }

  function render(now) {
    if (disposed || paused || !loaded) return;
    const dt = lastTime === null ? 0 : Math.min((now - lastTime) / 1000, 0.05);
    lastTime = now;
    elapsed += dt;
    pointer.lerp(targetPointer, 1.0 - Math.pow(0.0007, dt));
    const ease = 1.0 - Math.pow(0.0012, dt);
    root.rotation.y += (pointer.x * PRESET.mouseAmount - root.rotation.y) * ease;
    root.rotation.x += ((pointer.y * PRESET.mouseAmount * 0.40 - 0.015) - root.rotation.x) * ease;
    for (const material of materials) {
      material.uniforms.uTime.value = reducedMotion ? 0 : elapsed;
      material.uniforms.uPhase.value = reducedMotion ? 0 : elapsed * PRESET.drift;
    }
    composer.render();
  }
  function animate(now) {
    raf = 0;
    if (disposed || paused || !loaded) return;
    sampleFramePacing(now);
    const frameBudget = targetFrameMs();
    // Small tolerance prevents a nominal 60 fps stream from being accidentally
    // halved to 30 fps because rAF timestamps land a fraction below 16.67 ms.
    if (!lastFrameStamp || now - lastFrameStamp >= frameBudget - 1.0) {
      lastFrameStamp = now;
      render(now);
    }
    raf = requestAnimationFrame(animate);
  }
  function refresh() {
    cancelAnimationFrame(raf);
    raf = 0;
    lastTime = null;
    lastFrameStamp = 0;
    lastRafStamp = 0;
    slowFrameStreak = 0;
    if (disposed || paused || !loaded) return;
    render(performance.now());
    raf = requestAnimationFrame(animate);
  }
  function resize() {
    if (disposed || !composer) return;
    const width = Math.max(container.clientWidth, 1), height = Math.max(container.clientHeight, 1);
    const q = quality();
    const maxPixels = coarsePointer ? PERFORMANCE.touchMaxPixels : q.maxPixels;
    const maxDpr = coarsePointer ? PERFORMANCE.touchMaxDpr : q.maxDpr;
    const nativeDpr = Math.min(devicePixelRatio || 1, maxDpr);
    const budgetDpr = Math.sqrt(maxPixels / Math.max(1, width * height));
    const pixelRatio = Math.max(0.38, Math.min(nativeDpr, budgetDpr));
    syncPerformanceClass();
    renderer.setPixelRatio(pixelRatio);
    renderer.setSize(width, height, false);
    composer.setPixelRatio(pixelRatio);
    composer.setSize(width, height);
    camera.aspect = width / height;
    const halfView = Math.tan(THREE.MathUtils.degToRad(camera.fov * 0.5));
    // Optical fit leaves the reference's view-space scan field and line density intact.
    camera.zoom = 0.95 * halfView / Math.max(fitY, fitX / camera.aspect);
    camera.updateProjectionMatrix();
    camera.projectionMatrix.elements[8] = fitCenter.x * camera.zoom / (halfView * camera.aspect);
    camera.projectionMatrix.elements[9] = fitCenter.y * camera.zoom / halfView;
    camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert();
    refresh();
  }

  try {
    renderer = new THREE.WebGLRenderer({ canvas, antialias: !coarsePointer, alpha: true, premultipliedAlpha: true, powerPreference: coarsePointer ? 'low-power' : 'high-performance' });
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.NeutralToneMapping;
    renderer.toneMappingExposure = 1.00;
    renderer.debug.onShaderError = (gl, program, vertex, fragment) => {
      if (shaderFailed || disposed) return;
      shaderFailed = true;
      const details = [gl.getProgramInfoLog(program), gl.getShaderInfoLog(vertex), gl.getShaderInfoLog(fragment)].filter(Boolean).join('\n');
      queueMicrotask(() => fail(new Error(`Head scan shader failed: ${details}`)));
    };
    composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));
    // Bloom was visually negligible at the approved 0.012 strength but still
    // required another full-resolution post-processing pass on every frame.
    outputPass = new OutputPass();
    // Preserve the reference RGB over black, but make its black signal transparent.
    // The canvas consumes premultiplied RGB, so alpha must be at least max(R,G,B).
    outputPass.material.fragmentShader = outputPass.material.fragmentShader.replace(/\}\s*$/, `
      gl_FragColor.a = clamp(max(max(gl_FragColor.r, gl_FragColor.g), gl_FragColor.b), 0.0, 1.0);
    }`);
    composer.addPass(outputPass);
    canvas.addEventListener('webglcontextlost', onContextLost);
    if ('ResizeObserver' in window) {
      resizeObserver = new ResizeObserver(resize);
      resizeObserver.observe(container);
    } else addEventListener('resize', resize, { passive: true });
    resize();
  } catch (error) {
    destroy();
    throw error;
  }

  const ready = new GLTFLoader().loadAsync(modelUrl).then(async gltf => {
    if (disposed) { disposeModel(gltf.scene); return; }
    model = gltf.scene;
    model.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(model);
    const size = box.getSize(new THREE.Vector3());
    if (!Number.isFinite(size.x + size.y + size.z) || size.y <= 0) throw new Error('Invalid head model bounds.');
    const scale = 3.25 / size.y;
    model.position.sub(box.getCenter(new THREE.Vector3())).multiplyScalar(scale);
    model.scale.multiplyScalar(scale);
    const originalMaterials = new Set(), originalTextures = new Set();
    model.traverse(object => {
      if (!object.isMesh) return;
      if (!object.geometry.attributes.normal) object.geometry.computeVertexNormals();
      object.geometry.computeBoundingBox();
      const bounds = object.geometry.boundingBox;
      for (const material of [].concat(object.material)) {
        if (!material) continue;
        originalMaterials.add(material);
        for (const value of Object.values(material)) if (value?.isTexture) originalTextures.add(value);
      }
      const uniforms = {};
      for (const name of ['frequency', 'depthWarp', 'lineWidth', 'noiseStrength', 'noiseScale', 'glow', 'fadeLow', 'fadeHigh']) {
        uniforms[`u${name[0].toUpperCase()}${name.slice(1)}`] = { value: PRESET[name] };
      }
      Object.assign(uniforms, {
        uTime: { value: 0 }, uPhase: { value: 0 },
        uBoundsMin: { value: bounds.min.clone() }, uBoundsMax: { value: bounds.max.clone() }
      });
      object.material = new THREE.ShaderMaterial({ uniforms, vertexShader, fragmentShader, side: THREE.FrontSide, depthTest: true, depthWrite: true, transparent: false, toneMapped: false });
      materials.push(object.material);
    });
    originalMaterials.forEach(material => material.dispose());
    originalTextures.forEach(texture => texture.dispose());
    root.add(model);

    // Fit the visible geometry across the full interaction range. The previous
    // implementation projected every vertex at 25 rotations, which created a
    // long main-thread task on mobile. A deterministic topology sample is
    // visually equivalent for framing while bounding CPU work.
    const points = [], vertex = new THREE.Vector3();
    const fitMeshes = [];
    model.updateMatrixWorld(true);
    const inverseRoot = root.matrixWorld.clone().invert();
    model.traverse(object => {
      if (object.isMesh) fitMeshes.push(object);
    });
    const fitSampleBudget = coarsePointer ? 2200 : 7000;
    const perMeshBudget = Math.max(64, Math.floor(fitSampleBudget / Math.max(1, fitMeshes.length)));
    for (const object of fitMeshes) {
      const positions = object.geometry.attributes.position, bounds = object.geometry.boundingBox;
      if (!positions || !bounds) continue;
      const matrix = inverseRoot.clone().multiply(object.matrixWorld);
      const low = bounds.min.y + (bounds.max.y - bounds.min.y) * PRESET.fadeLow;
      const stride = Math.max(1, Math.ceil(positions.count / perMeshBudget));
      for (let i = 0; i < positions.count; i += stride) {
        vertex.fromBufferAttribute(positions, i);
        if (vertex.y >= low) points.push(vertex.clone().applyMatrix4(matrix));
      }
    }
    if (!points.length) throw new Error('No visible head geometry.');

    // Yield after model/material setup so loading cannot monopolize a full
    // interaction frame on constrained devices.
    await new Promise(resolve => requestAnimationFrame(() => resolve()));

    camera.updateMatrixWorld(true);
    const projected = new THREE.Box2(), point = new THREE.Vector2(), matrix = new THREE.Matrix4();
    for (const y of [-1, -0.5, 0, 0.5, 1]) {
      for (const x of [-1, -0.5, 0, 0.5, 1]) {
        const yaw = y * PRESET.mouseAmount, pitch = x * PRESET.mouseAmount * 0.40 - 0.015;
        root.rotation.set(pitch, yaw, 0);
        root.updateMatrixWorld(true);
        matrix.multiplyMatrices(camera.matrixWorldInverse, root.matrixWorld);
        for (const p of points) {
          vertex.copy(p).applyMatrix4(matrix);
          point.set(vertex.x / -vertex.z, vertex.y / -vertex.z);
          projected.expandByPoint(point);
        }
      }
      if (coarsePointer) await new Promise(resolve => requestAnimationFrame(() => resolve()));
    }
    projected.getCenter(fitCenter);
    fitX = (projected.max.x - projected.min.x) * 0.5;
    fitY = (projected.max.y - projected.min.y) * 0.5;
    root.rotation.set(-0.015, 0, 0);
    root.updateMatrixWorld(true);
    loaded = true;
    resize();
    // Shader compilation can itself be expensive on mobile. Give layout and
    // projection work a frame to settle before compiling the first render.
    if (coarsePointer) await new Promise(resolve => requestAnimationFrame(() => resolve()));
    composer.render();
  }).catch(fail);

  return {
    renderer, scene, camera, root, materials, preset: PRESET, ready,
    get disposed() { return disposed; },
    setPointer(x, y) {
      if (disposed) return;
      targetPointer.set(THREE.MathUtils.clamp(x, -1, 1), THREE.MathUtils.clamp(y, -1, 1));
    },
    setPaused(value) {
      if (paused === value || disposed) return;
      paused = value;
      refresh();
    },
    setReducedMotion(value) {
      reducedMotion = value;
      pointer.set(0, 0);
      targetPointer.set(0, 0);
      root.rotation.set(-0.015, 0, 0);
      refresh();
    },
    destroy
  };
}
